from typing import List

class Solution:
    def findShortestSubArray(self, nums: List[int]) -> int:
        count = {}
        first = {}
        last = {}
        for i, num in enumerate(nums):
            if num not in count:
                count[num] = 0
                first[num] = i
                last[num] = i
            count[num] += 1
            last[num] = i

        degree = max(count.values())
        return min(last[num] - first[num] + 1 for num in count if count[num] == degree)
```

