from typing import List

class Solution:
    def validMountainArray(self, A: List[int]) -> bool:
        n = len(A)
        if n < 3:
            return False

        i = 0

        # Go up
        while i + 1 < n and A[i] < A[i + 1]:
            i += 1

        # Peak cannot be first or last
        if i == 0 or i == n - 1:
            return False

        # Go down
        while i + 1 < n and A[i] > A[i + 1]:
            i += 1

        return i == n - 1
